import { parseNumericToken } from './number-token.mjs';

export class ArgumentParserError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgumentParserError';
  }
}

export class HelpRequested extends Error {
  constructor() {
    super('help');
    this.name = 'HelpRequested';
  }
}

export function parseCommandLine(argv) {
  let amount1;
  let amount2;
  let currency;
  const unknownArguments = [];

  for (let index = 2; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--') {
      unknownArguments.push(...argv.slice(index + 1));
      break;
    }

    if (token === '-h' || token === '--help') {
      throw new HelpRequested();
    }

    if (token === '--amount1' || token.startsWith('--amount1=')) {
      const { nextIndex, rawValue } = readOptionValue(argv, index, '--amount1');
      amount1 = parseAmountValue('--amount1', rawValue);
      index = nextIndex;
      continue;
    }

    if (token === '--amount2' || token.startsWith('--amount2=')) {
      const { nextIndex, rawValue } = readOptionValue(argv, index, '--amount2');
      amount2 = parseAmountValue('--amount2', rawValue);
      index = nextIndex;
      continue;
    }

    if (token === '--currency' || token.startsWith('--currency=')) {
      const { nextIndex, rawValue } = readOptionValue(argv, index, '--currency');
      currency = rawValue;
      index = nextIndex;
      continue;
    }

    unknownArguments.push(token);
  }

  if (unknownArguments.length > 0) {
    throw new ArgumentParserError(`unrecognized arguments: ${unknownArguments.join(' ')}`);
  }

  const missingArguments = [];
  if (amount1 === undefined) {
    missingArguments.push('--amount1');
  }
  if (amount2 === undefined) {
    missingArguments.push('--amount2');
  }
  if (currency === undefined) {
    missingArguments.push('--currency');
  }

  if (missingArguments.length > 0) {
    throw new ArgumentParserError(
      `the following arguments are required: ${missingArguments.join(', ')}`,
    );
  }

  return { amount1, amount2, currency };
}

function parseAmountValue(optionName, rawValue) {
  const parsedToken = parseNumericToken(rawValue);
  if (parsedToken === null) {
    throw new ArgumentParserError(`argument ${optionName}: invalid float value: '${rawValue}'`);
  }

  return parsedToken;
}

function readOptionValue(argv, index, optionName) {
  const token = argv[index];
  const attachedPrefix = `${optionName}=`;

  if (token.startsWith(attachedPrefix)) {
    return {
      nextIndex: index,
      rawValue: token.slice(attachedPrefix.length),
    };
  }

  const nextToken = argv[index + 1];
  if (nextToken === undefined || isReservedOptionToken(nextToken)) {
    throw new ArgumentParserError(`argument ${optionName}: expected one argument`);
  }

  return {
    nextIndex: index + 1,
    rawValue: nextToken,
  };
}

function isReservedOptionToken(token) {
  return (
    token === '-h' ||
    token === '--help' ||
    token === '--amount1' ||
    token === '--amount2' ||
    token === '--currency' ||
    token.startsWith('--amount1=') ||
    token.startsWith('--amount2=') ||
    token.startsWith('--currency=')
  );
}

