const SPECIAL_FLOAT_PATTERN = /^[+-]?(?:inf(?:inity)?|nan)$/iu;
const DECIMAL_FLOAT_PATTERN =
  /^[+-]?(?:(?:\d(?:_?\d)*)\.(?:\d(?:_?\d)*)?|\.(?:\d(?:_?\d)*)|(?:\d(?:_?\d)*))(?:[eE][+-]?\d(?:_?\d)*)?$/u;

export function parseNumericToken(rawToken) {
  if (!SPECIAL_FLOAT_PATTERN.test(rawToken) && !DECIMAL_FLOAT_PATTERN.test(rawToken)) {
    return null;
  }

  const normalizedToken = rawToken.replace(/_/gu, '');
  const sign = normalizedToken.startsWith('-') ? -1 : 1;

  if (/^[+-]?nan$/iu.test(normalizedToken)) {
    return {
      kind: 'nan',
      numericValue: Number.NaN,
      rawToken,
      sign,
    };
  }

  if (/^[+-]?inf(?:inity)?$/iu.test(normalizedToken)) {
    return {
      kind: 'infinity',
      numericValue: sign < 0 ? Number.NEGATIVE_INFINITY : Number.POSITIVE_INFINITY,
      rawToken,
      sign,
    };
  }

  const numericValue = Number(normalizedToken);
  if (Number.isNaN(numericValue)) {
    return null;
  }

  return {
    kind: 'finite',
    numericValue,
    plainDecimal: toPlainDecimal(normalizedToken),
    rawToken,
    sign,
  };
}

export function formatAbsoluteNumber(parsedToken, fractionDigits) {
  if (parsedToken.kind === 'infinity') {
    return 'INF';
  }

  if (parsedToken.kind === 'nan') {
    return 'NAN';
  }

  return roundHalfEvenToFixed(parsedToken.plainDecimal, fractionDigits);
}

function toPlainDecimal(normalizedToken) {
  let unsignedToken = normalizedToken;
  if (unsignedToken.startsWith('+') || unsignedToken.startsWith('-')) {
    unsignedToken = unsignedToken.slice(1);
  }

  const exponentIndex = unsignedToken.search(/[eE]/u);
  const coefficientText =
    exponentIndex === -1 ? unsignedToken : unsignedToken.slice(0, exponentIndex);
  const exponentText =
    exponentIndex === -1 ? '0' : unsignedToken.slice(exponentIndex + 1);
  const exponent = Number(exponentText);
  const [rawWholePart = '0', fractionalPart = ''] = coefficientText.split('.');
  const wholePart = rawWholePart === '' ? '0' : rawWholePart;
  const mergedDigits = `${wholePart}${fractionalPart}` || '0';
  const decimalIndex = wholePart.length + exponent;

  let plainDecimal;
  if (decimalIndex <= 0) {
    plainDecimal = `0.${'0'.repeat(-decimalIndex)}${mergedDigits}`;
  } else if (decimalIndex >= mergedDigits.length) {
    plainDecimal = `${mergedDigits}${'0'.repeat(decimalIndex - mergedDigits.length)}`;
  } else {
    plainDecimal = `${mergedDigits.slice(0, decimalIndex)}.${mergedDigits.slice(decimalIndex)}`;
  }

  return normalizePlainDecimal(plainDecimal);
}

function normalizePlainDecimal(plainDecimal) {
  let [wholePart, fractionalPart = ''] = plainDecimal.split('.');
  wholePart = wholePart.replace(/^0+(?=\d)/u, '');
  if (wholePart === '') {
    wholePart = '0';
  }

  fractionalPart = fractionalPart.replace(/0+$/u, '');
  return fractionalPart === '' ? wholePart : `${wholePart}.${fractionalPart}`;
}

function roundHalfEvenToFixed(plainDecimal, fractionDigits) {
  let [wholePart, fractionalPart = ''] = plainDecimal.split('.');
  wholePart = wholePart.replace(/^0+(?=\d)/u, '');
  if (wholePart === '') {
    wholePart = '0';
  }

  if (fractionalPart.length < fractionDigits) {
    return fractionDigits === 0
      ? wholePart
      : `${wholePart}.${fractionalPart.padEnd(fractionDigits, '0')}`;
  }

  if (fractionalPart.length === fractionDigits) {
    return fractionDigits === 0 ? wholePart : `${wholePart}.${fractionalPart}`;
  }

  const keptFraction = fractionalPart.slice(0, fractionDigits);
  const discardedFraction = fractionalPart.slice(fractionDigits);
  let scaledDigits = `${wholePart}${keptFraction}`.replace(/^0+(?=\d)/u, '');
  if (scaledDigits === '') {
    scaledDigits = '0';
  }

  if (shouldRoundUp(wholePart, keptFraction, discardedFraction)) {
    scaledDigits = incrementDigits(scaledDigits);
  }

  return toFixedFromScaledDigits(scaledDigits, fractionDigits);
}

function shouldRoundUp(wholePart, keptFraction, discardedFraction) {
  const firstDiscardedDigit = discardedFraction[0];
  if (firstDiscardedDigit > '5') {
    return true;
  }

  if (firstDiscardedDigit < '5') {
    return false;
  }

  if (/[1-9]/u.test(discardedFraction.slice(1))) {
    return true;
  }

  const referenceDigits = keptFraction === '' ? wholePart : keptFraction;
  const lastRetainedDigit = referenceDigits[referenceDigits.length - 1] ?? '0';
  return Number(lastRetainedDigit) % 2 === 1;
}

function incrementDigits(digits) {
  const digitArray = digits.split('');

  for (let index = digitArray.length - 1; index >= 0; index -= 1) {
    if (digitArray[index] !== '9') {
      digitArray[index] = String(Number(digitArray[index]) + 1);
      return digitArray.join('');
    }

    digitArray[index] = '0';
  }

  digitArray.unshift('1');
  return digitArray.join('');
}

function toFixedFromScaledDigits(scaledDigits, fractionDigits) {
  if (fractionDigits === 0) {
    return scaledDigits;
  }

  const paddedDigits = scaledDigits.padStart(fractionDigits + 1, '0');
  const wholeLength = paddedDigits.length - fractionDigits;
  return `${paddedDigits.slice(0, wholeLength)}.${paddedDigits.slice(wholeLength)}`;
}

